SELECT CASE WHEN c.credit_limit >= 14800 THEN 'high' WHEN c.credit_limit >= 3500 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, c.is_active, MIN(o.order_date) AS first_order_date FROM orders o INNER JOIN stores s ON o.store_id = s.id INNER JOIN customers c ON o.customer_id = c.id GROUP BY CASE WHEN c.credit_limit >= 14800 THEN 'high' WHEN c.credit_limit >= 3500 THEN 'mid' ELSE 'low' END, c.is_active ORDER BY first_order_date, credit_limit_bucket
